+import "testing"
+
+func TestBalance(t *testing.T) {
+	l := &Ledger{}
+
+	// Post a credit of 300 to account1 and a debit of 100 to account2,
+	// balanced against account3 (credit 100, debit 300)
+	err := l.Post(
+		Entry{AccountID: "account1", AmountCents: 300, Currency: "USD"},
+		Entry{AccountID: "account2", AmountCents: -100, Currency: "USD"},
+		Entry{AccountID: "account3", AmountCents: -300, Currency: "USD"},
+		Entry{AccountID: "account3", AmountCents: 100, Currency: "USD"},
+	)
