+		t.Fatalf("Post failed: %v", err)
+	}
+
+	if got := l.Balance("account1"); got != 300 {
+		t.Errorf("account1 balance = %d; want 300", got)
+	}
+	if got := l.Balance("account2"); got != -100 {
+		t.Errorf("account2 balance = %d; want -100", got)
+	}
+	if got := l.Balance("account3"); got != -200 {
+		t.Errorf("account3 balance = %d; want -200", got)
+	}
+}

